function x(u,r,n=5){if(Array.isArray(r))return r;const e=u.filter(o=>typeof o=="number"&&isFinite(o)).sort((o,l)=>o-l);if(e.length===0)return[];const i=e[0],c=e[e.length-1];if(i===c)return[i,c];if(r==="equal"){const o=(c-i)/n,l=[i];for(let t=1;t<n;t++)l.push(i+o*t);return l.push(c),l}if(r==="quantile"){const o=[i],l=e.length;for(let t=1;t<n;t++){const f=(l-1)*(t/n),g=Math.floor(f),p=f-g;o.push(e[g+1]!==void 0?e[g]+p*(e[g+1]-e[g]):e[g])}return o.push(c),o}if(r==="jenks"){const o=k(e,n);return[i,...o,c]}return[]}function k(u,r){const n=u.length,e=Array.from({length:n+1},()=>new Array(r+1).fill(0)),i=Array.from({length:n+1},()=>new Array(r+1).fill(0));for(let t=1;t<=r;t++){e[1][t]=1,i[1][t]=0;for(let f=2;f<=n;f++)i[f][t]=1/0}let c=0;for(let t=2;t<=n;t++){let f=0,g=0,p=0;for(let y=1;y<=t;y++){const s=t-y+1,A=u[s-1];g+=A*A,f+=A,p++,c=g-f*f/p;const j=s-1;if(j!==0)for(let h=2;h<=r;h++)i[t][h]>=c+i[j][h-1]&&(e[t][h]=s,i[t][h]=c+i[j][h-1])}e[t][1]=1,i[t][1]=c}const o=new Array(r+1);o[r]=u[n-1],o[0]=u[0];let l=n;for(let t=r;t>=2;t--){const f=e[l][t]-2;o[t-1]=u[f],l=e[l][t]-1}return o.slice(1,r)}function w(u,r){if(r.length<2)return 0;for(let n=1;n<r.length;n++)if(u<=r[n])return n-1;return r.length-2}export{x as calculateBreaks,w as getClassIndex};
